@dataclass(frozen=True)
class KnownOneof:
    tag: Literal["known"]
    arm: str
    payload: KnownOneofPayload


@dataclass(frozen=True)
class UnknownOneof:
    raw_payload: bytes
    tag: Literal["unknown"] = "unknown"


def known_oneof(payload: KnownOneofPayload) -> KnownOneof:
    return KnownOneof(tag="known", arm=payload.arm, payload=payload)


def encode_wire_choice(value: WireChoice) -> dict[str, object]:
    checked = oneof_arm(value)
    if isinstance(checked, KnownOneof):
        return {"tag": "known", "arm": checked.arm, "payload": checked.payload}
    return {"tag": "unknown", "raw_payload": checked.raw_payload}


def decode_wire_choice(value: object) -> WireChoice:
    if not isinstance(value, dict):
        raise TypeError("wire_choice must decode from an object")
    tag = value.get("tag")
    if tag == "known":
        payload = value.get("payload")
        if not isinstance(payload, tuple(KNOWN_ONEOF_PAYLOAD_TYPES)):
            raise TypeError("known oneof payload must be a generated Rust arm")
        arm = value.get("arm")
        if arm != payload.arm:
            raise ValueError("known oneof arm does not match payload")
        return KnownOneof(tag="known", arm=arm, payload=payload)
    if tag == "unknown":
        raw_payload = value.get("raw_payload")
        if not isinstance(raw_payload, bytes):
            raise TypeError("unknown oneof payload must be bytes")
        return UnknownOneof(raw_payload=raw_payload)
