def _message_unknown_wire_bytes(message: object) -> bytes | None:
    """Return an opaque message payload when protobuf has unknown fields.

    The protobuf runtime does not identify an unknown field's future oneof
    membership. Keep the whole serialized message as a message-level opaque
    value instead of guessing that unrelated unknown fields belong to one
    particular union.
    """
    try:
        raw = bytes(message.SerializeToString())
        unknown = message.UnknownFields()
        if len(unknown) > 0:
            return raw
    except Exception:
        # The upb-backed Python runtime exposes UnknownFields as a deliberate
        # NotImplementedError.  Its supported inspection path is to copy the
        # message, discard unknown fields, and compare the wire bytes.
        try:
            raw = bytes(message.SerializeToString())
            known = type(message)()
            known.CopyFrom(message)
            known.DiscardUnknownFields()
            if bytes(known.SerializeToString()) != raw:
                return raw
        except Exception:
            pass
    raw_unknown = getattr(message, "_unknown_fields", None)
    if raw_unknown:
        return bytes(message.SerializeToString())
    return None


@dataclass(frozen=True)
class Credentials:
    """Credentials accepted by the generated remote facade.

    A zero-value credential uses the platform trust store. Supplying a client
    certificate enables mTLS; bearer credentials are attached by gRPC call
    credentials and never need to be copied into individual RPC calls.
    """

    bearer_token: str | None = None
    root_certificates: bytes | None = None
    certificate_chain: bytes | None = None
    private_key: bytes | None = None

    @classmethod
    def bearer(cls, token: str) -> "Credentials":
        return cls(bearer_token=token)

    @classmethod
    def mtls(
        cls,
        certificate_chain: bytes,
        private_key: bytes,
        root_certificates: bytes | None = None,
        bearer_token: str | None = None,
    ) -> "Credentials":
        return cls(
            bearer_token=bearer_token,
            root_certificates=root_certificates,
            certificate_chain=certificate_chain,
            private_key=private_key,
        )


